    "source": "/** Fenwick tree (binary indexed tree), teaching version.\n *  Public API: 0-based indices, half-open ranges [l, r). Internally tree is 1-based. */\npublic class Fenwick {\n    int n;\n    long[] tree; // tree[0] is unused\n\n    Fenwick(int n) {\n        this.n = n;\n        this.tree = new long[n + 1];\n    }\n\n    /** a[i] += delta (i is 0-based). */\n    void add(int i, long delta) {\n        int p = i + 1;\n        while (p <= n) {\n            tree[p] += delta;\n            p += p & -p;\n        }\n    }\n\n    /** Sum of a[0..r). */\n    long prefix(int r) {\n        long sum = 0;\n        int p = r;\n        while (p > 0) {\n            sum += tree[p];\n            p -= p & -p;\n        }\n        return sum;\n    }\n\n    /** Sum of a[l..r). */\n    long range(int l, int r) {\n        return prefix(r) - prefix(l);\n    }\n}\n",
