    "source": "/// Fenwick tree (binary indexed tree), teaching version.\n/// Public API: 0-based indices, half-open ranges [l, r). Internally tree is 1-based.\npub struct Fenwick {\n    n: usize,\n    tree: Vec<i64>, // tree[0] is unused\n}\n\nimpl Fenwick {\n    pub fn new(n: usize) -> Self {\n        Fenwick { n, tree: vec![0; n + 1] }\n    }\n\n    /// a[i] += delta (i is 0-based).\n    pub fn add(&mut self, i: usize, delta: i64) {\n        let mut p = i + 1;\n        while p <= self.n {\n            self.tree[p] += delta;\n            p += p & p.wrapping_neg();\n        }\n    }\n\n    /// Sum of a[0..r).\n    pub fn prefix(&self, r: usize) -> i64 {\n        let mut sum = 0;\n        let mut p = r;\n        while p > 0 {\n            sum += self.tree[p];\n            p -= p & p.wrapping_neg();\n        }\n        sum\n    }\n\n    /// Sum of a[l..r).\n    pub fn range(&self, l: usize, r: usize) -> i64 {\n        self.prefix(r) - self.prefix(l)\n    }\n}\n",
